import { sharedFilters } from "@/fineliner/pen/filters"

const filters = sharedFilters()

/** The shared SVG filters every frame and rule refers to. Render once, inside <body>. */
export function FinelinerDefs() {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      width="0"
      height="0"
      style={{ position: "absolute" }}
      dangerouslySetInnerHTML={{ __html: filters }}
    />
  )
}

import { isValidElement, type CSSProperties, type ReactNode } from "react"
import { frameVars } from "@/fineliner/pen/filters"
import { seedOf } from "@/fineliner/pen/seed"

// Base UI lets a style be a function of the component's state; plain elements take an object.
type StyleProp<State> =
  CSSProperties | ((state: State) => CSSProperties | undefined) | undefined

/**
 * A floating sheet's distance from its trigger (Base UI's sideOffset). The pen-shadow lies 7px right of and below the
 * sheet, so a sheet that opens above or to the left stands 7px further off, clear of the trigger's frame.
 */
export const clearOfShadow = ({ side }: { side: string }) =>
  /^(top|left|inline-start)$/.test(side) ? 11 : 4

/** Room a floating sheet keeps from the viewport's edges (Base UI's collisionPadding): more right and below, where the
 * pen-shadow falls, so the shadow never pushes a phone page sideways. */
export const shadowRoom = { top: 5, left: 5, right: 12, bottom: 12 }

/** The words in a node, elements included: "Add a record" from [<PlusIcon />, <span> Add a record</span>]. */
export function wordsOf(node: ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(wordsOf).join("")
  if (isValidElement<{ children?: ReactNode }>(node))
    return wordsOf(node.props.children)
  return ""
}

/**
 * The seeded custom properties a drawn frame reads (which wobble, how far each edge runs past its corners), taken
 * from a control's own words so neighbouring buttons wobble differently and each always the same way. A control with
 * no words (an icon alone) keeps the default wobble. A caller's own style wins.
 */
export function frameStyle(
  source: ReactNode,
  style?: CSSProperties,
): CSSProperties | undefined
export function frameStyle<State>(
  source: ReactNode,
  style?: StyleProp<State>,
): StyleProp<State>
export function frameStyle<State>(
  source: ReactNode,
  style?: StyleProp<State>,
): StyleProp<State> {
  const words = wordsOf(source).trim()
  if (!words) return style
  const vars = frameVars(seedOf(words)) as CSSProperties
  if (typeof style === "function")
    return (state: State) => ({ ...vars, ...style(state) })
  return { ...vars, ...style }
}

// No React here: drawing-takes.ts uses this on pages that run no React.

/** Every id the markup declares, and every reference to one, with `-suffix` added. */
export function ownIds(markup: string, suffix: string) {
  const ids = [...markup.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1])
  if (ids.length === 0) return markup
  const own = new Set(ids)
  return markup.replace(
    /(\sid="|url\(#|href="#)([^")]+)/g,
    (match, lead: string, id: string) =>
      own.has(id) ? `${lead}${id}-${suffix}` : match,
  )
}

import { useCallback, useId } from "react"
import { ownIds } from "./own-ids"

/**
 * Pen markup names its masks from the seed, so two copies of the same drawing on one page share ids, and when the
 * first copy is hidden (display: none) the second loses its masks. This gives every id the markup declares a suffix
 * of this instance's own, and points its references at it.
 */
export function useOwnIds(): (markup: string) => string {
  const suffix = useId().replace(/[^\w-]/g, "")
  return useCallback((markup: string) => ownIds(markup, suffix), [suffix])
}

import { createCn } from "cn/config"

// Class merging that knows Fineliner's theme. Without this, cn reads `text-small` or `text-label` as a text colour and
// drops it when a colour class such as `text-pen` follows; the same goes for the φ spacing names and the voices.
// Every kit component imports cn from here, not from "cn".
export const cn = createCn({
  extend: {
    theme: {
      text: [
        "label",
        "small",
        "ui",
        "body",
        "lead",
        "h2",
        "h1",
        "title",
        "display",
      ],
      leading: ["body", "small", "ui", "heading", "subhead", "display", "lead"],
      spacing: [
        "hair",
        "tight",
        "snug",
        "line",
        "section",
        "page",
        "control",
        "control-compact",
      ],
      font: ["read", "type", "label", "hand", "ui"],
    },
  },
})

// The wobble that turns a crisp CSS border into a slow hand. One copy of each filter lives in the document
// (FinelinerDefs); frames pick a variant from their seed, so neighbouring frames wobble differently.
import { stream } from "./seed"

/** How many wobble variants exist per hand. */
export const WOBBLE_VARIANTS = 6

/** A displacement filter at a low frequency: lines bend slowly rather than jitter. Lively bends about three times as far. */
export function wobbleFilter(
  id: string,
  variant: number,
  hand: "calm" | "lively",
) {
  const frequency = (0.011 + (variant % 3) * 0.005).toFixed(3)
  const scale =
    hand === "lively" ? 2.4 + (variant % 4) * 0.35 : 0.8 + (variant % 3) * 0.2
  return `<filter id="${id}" x="-20%" y="-20%" width="140%" height="140%"><feTurbulence type="fractalNoise" baseFrequency="${frequency}" numOctaves="1" seed="${variant * 7 + 4}"/><feDisplacementMap in="SourceGraphic" scale="${scale.toFixed(2)}" xChannelSelector="R" yChannelSelector="G"/></filter>`
}

/** Every shared filter, as one string for a hidden <svg>: fl-wob-1…6 and fl-wob-calm-1…6. */
export function sharedFilters() {
  return Array.from(
    { length: WOBBLE_VARIANTS },
    (_, i) =>
      wobbleFilter(`fl-wob-${i + 1}`, i, "lively") +
      wobbleFilter(`fl-wob-calm-${i + 1}`, i, "calm"),
  ).join("")
}

/**
 * The custom properties a frame reads: which wobble it uses (--wob) and how far each edge runs past its corners
 * (--o1 top, --o2 right, --o3 bottom, --o4 left, as fractions of the hand's --over; negative stops short).
 */
export function frameVars(seed: number): Record<string, string> {
  const r = stream(seed, "frame")
  const vars: Record<string, string> = {
    "--wob": `var(--wob-${1 + Math.floor(r.next() * WOBBLE_VARIANTS)})`,
  }
  for (let n = 1; n <= 4; n++) vars[`--o${n}`] = r.between(-0.2, 1).toFixed(2)
  return vars
}

// Every random choice in Fineliner comes from a seed, so the same seed draws the same thing on the server, in the
// browser and in every build. Patina UI's seed functions, unchanged (Patina ported them from Mental Models).

/** FNV-1a over UTF-16 code units, reduced to 31 bits. */
export function seedOf(text: string | number): number {
  return (
    ([...String(text)].reduce(
      (h, c) => Math.imul(h ^ c.charCodeAt(0), 16777619),
      2166136261,
    ) >>>
      0) %
    2 ** 31
  )
}

/** A small seeded PRNG (mulberry32 family) returning values in [0, 1). */
export function prng(seed: number): () => number {
  let s = seed >>> 0
  return () => {
    s = (s + 0x6d2b79f5) >>> 0
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** A labelled sub-seed. Each kind of decision draws from its own fork, so adding a new one leaves the rest unchanged. */
export function fork(seed: number, label: string): number {
  return seedOf(`${seed}:${label}`)
}

/** A PRNG with a helper for ranges, drawn from a labelled fork. */
export function stream(seed: number, label: string) {
  const next = prng(fork(seed, label))
  return {
    next,
    between: (a: number, b: number) => a + next() * (b - a),
    /** A signed unit value in [-1, 1). */
    signed: () => next() * 2 - 1,
    pick: <T>(items: readonly T[]): T =>
      items[Math.floor(next() * items.length)] as T,
    /** True with probability p. */
    chance: (p: number) => next() < p,
  }
}

export type Stream = ReturnType<typeof stream>

/* Page-level defaults: the paper, the reading voice, links, focus, scrollbars and the accessibility fallbacks. */

/* The paper's layers stack at their own tile sizes, which share no factors, so the paper never visibly repeats. The
   page lays them in two parts: the grain (tooth, relief, mottle), whose filters are slow to paint, lies still on a
   layer of its own under the page, painted once rather than wherever something on the page changes; the specks
   (flecks, fibres) lie over it on the body and travel with the page. Small surfaces (menus, a sticky table head) take
   the whole stack. */
:root {
  --paper-specks: var(--tex-flecks), var(--tex-fibres);
  --paper-specks-size: 719px, 613px;
  --paper-grain: var(--tex-tooth), var(--tex-relief), var(--tex-mottle);
  --paper-grain-size: 353px, 541px, 1201px;
  --paper-texture: var(--paper-specks), var(--paper-grain);
  --paper-texture-size: var(--paper-specks-size), var(--paper-grain-size);
}

@layer base {
  /* The paper's colour lies on the root, so it fills the whole window however short the page; the stable gutter keeps
     the page from shifting sideways between pages that scroll and pages that don't. */
  html {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
    scrollbar-gutter: stable;
    background-color: var(--paper);
  }
  /* The grain, as tall as the largest viewport, so a phone's toolbar sliding away never resizes it. */
  html::before {
    content: "";
    position: fixed;
    inset: 0 0 auto;
    height: 100vh;
    height: 100lvh;
    z-index: -1;
    pointer-events: none;
    background-image: var(--paper-grain);
    background-size: var(--paper-grain-size);
    will-change: transform;
  }

  /* The specks, at least a window tall, so they reach the bottom of a short page. */
  body {
    min-height: 100vh;
    min-height: 100svh;
    background-image: var(--paper-specks);
    background-size: var(--paper-specks-size);
    margin: 0;
    color: var(--pen);
    font-family: var(--face-ui);
    font-size: var(--type-body);
    line-height: var(--lh-body);
    font-optical-sizing: auto;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  /* Headings are quiet, like the words on a label: regular weight, set tight. */
  h1,
  h2,
  h3,
  h4 {
    font-family: var(--face-read);
    font-weight: 400;
    line-height: var(--lh-heading);
    letter-spacing: -0.012em;
    text-wrap: balance;
  }

  h3,
  h4 {
    font-weight: 500;
    line-height: var(--lh-subhead);
  }

  p,
  li {
    text-wrap: pretty;
  }

  a {
    color: inherit;
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--pen) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.2em;
  }
  a:hover {
    text-decoration-color: var(--pen);
  }

  :focus-visible {
    outline: 1.5px dashed var(--pen);
    outline-offset: 4px;
  }

  ::selection {
    background: var(--pen);
    color: var(--paper);
  }

  /* Scrollbars in pencil: a narrow thumb on no track that firms while hovered, the page's own included. */
  @supports not selector(::-webkit-scrollbar) {
    * {
      scrollbar-width: thin;
      scrollbar-color: var(
          --scrollbar-thumb,
          color-mix(in srgb, var(--pen) 55%, transparent)
        )
        transparent;
    }
  }
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    border: 3px solid transparent;
    border-radius: 999px;
    background: var(
        --scrollbar-thumb,
        color-mix(in srgb, var(--pen) 55%, transparent)
      )
      padding-box;
  }
  ::-webkit-scrollbar-thumb:hover {
    background-color: var(--scrollbar-thumb, var(--pen));
  }
  ::-webkit-scrollbar-corner {
    background: transparent;
  }

  svg {
    flex: none;
  }
}

/* More contrast asked for: flat paper and steady lines. */
@media (prefers-contrast: more) {
  :root {
    --paper-specks: none;
    --paper-grain: none;
    --over: 0px;
    --wob-1: none;
    --wob-2: none;
    --wob-3: none;
    --wob-4: none;
    --wob-5: none;
    --wob-6: none;
  }
}

/* Forced colours: the paper gives way to system colours, and frames to plain borders. */
@media (forced-colors: active) {
  :root {
    --paper-specks: none;
    --paper-grain: none;
  }
}

/* Controls: what people operate stays calm. Fields keep a steady pen line, because text sits inside them and a wobble
   filter would bend the text too; buttons, boxes, switches and triggers carry the drawn frame (frames.css). */

@utility control-field {
  border: var(--pen-weight) solid var(--input);
  border-radius: 2px 3px 2px 3px;
  background-color: transparent;
  color: var(--pen);
  font-family: var(--face-ui);
  font-size: var(--type-ui);
  line-height: var(--lh-ui);
  transition: box-shadow 120ms var(--ease-out);
  &::placeholder {
    color: var(--pen-quiet);
  }
  /* Hover presses the pen a little harder: a second, inset hairline instead of a wider border, so nothing moves. */
  &:hover:not(:disabled, [data-disabled]:not([data-disabled="false"])) {
    box-shadow: inset 0 0 0 0.65px var(--input);
  }
  &:disabled,
  &[data-disabled]:not([data-disabled="false"]) {
    cursor: not-allowed;
    border-style: dashed;
    color: var(--pen-faint);
  }
  &[aria-invalid="true"] {
    border-color: var(--correction);
    box-shadow: inset 0 -1.5px 0 var(--correction);
  }
}

/* A floating surface (menu, popover, select list): paper with its texture over the page, a drawn frame (pair it with
   the frame utility) and no blur. */
@utility float-sheet {
  background-color: var(--paper);
  background-image: var(--paper-texture);
  background-size: var(--paper-texture-size);
  color: var(--pen);
}

/* A term with its definition in a Tooltip: a dotted underline that firms up while the definition shows. Make the
   trigger focusable (tabIndex 0) so the definition opens from the keyboard too. */
@utility term {
  cursor: help;
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-color: color-mix(in srgb, currentColor 55%, transparent);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 0.25em;
  &:hover,
  &:focus-visible,
  &[data-popup-open] {
    text-decoration-color: currentColor;
  }
}

/* The pen puts a mark down: a tick, a dot or a fill wipes in from the left as it appears, and goes at once. Put it on
   anything that mounts or shows when chosen (an indicator, a pressed fill). */
@utility put-down {
  animation: fl-put-down var(--put-down) var(--ease-out);
}
@keyframes fl-put-down {
  from {
    clip-path: inset(-40% 100% -40% -40%);
  }
  to {
    clip-path: inset(-40%);
  }
}

/* Press: the control gives a little under the finger. */
@utility press {
  transition: scale var(--press) var(--ease-out);
  &:active:not(:disabled, [data-disabled]:not([data-disabled="false"])) {
    scale: 0.97;
  }
}

@media (prefers-reduced-motion: reduce) {
  .put-down {
    animation: fl-fade-in 100ms ease-out;
  }
  .press {
    transition: none;
  }
}
@keyframes fl-fade-in {
  from {
    opacity: 0;
  }
}

/* How the pen's drawings paint, and how their takes move. One weight for every line at every size (non-scaling
   strokes), so a 40px avatar and a 600px scene are drawn with the same pen. */

/* The drawing's box is a default the call site sizes (w-20, [&>svg]:h-6), so it sits in a layer below utilities. */
@layer components {
  /* Lettering in the pen's typefaces: display lines sit close. A caller's leading-* still wins (no specificity). */
  :where([data-slot="lettering"]) {
    line-height: 1.1;
  }
  /* Naïve Indie Inline: the outlines in the pen, its Fill font laid under them in the wash. Both fonts shape a line
     the same way, so the tint sits exactly between the outlines however the words wrap. */
  :where([data-slot="lettering"][data-face="inline"]) {
    position: relative;
    isolation: isolate;
  }
  :where([data-slot="lettering"][data-face="inline"])::before {
    content: attr(data-text);
    position: absolute;
    inset: 0;
    z-index: -1;
    font-family: var(--face-inline-fill);
    color: var(--wash);
    pointer-events: none;
  }
  @media (forced-colors: active) {
    :where([data-slot="lettering"][data-face="inline"])::before {
      display: none;
    }
  }
  .fl-drawing {
    display: block;
    width: 100%;
    height: auto;
    overflow: visible;
  }
}
.fl-drawing .ln {
  fill: none;
  stroke: currentColor;
  stroke-width: var(--pen-weight);
  vector-effect: non-scaling-stroke;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.fl-drawing .ink {
  fill: currentColor;
  stroke: currentColor;
  stroke-width: var(--pen-weight);
  vector-effect: non-scaling-stroke;
  stroke-linejoin: round;
}
.fl-drawing .wash {
  fill: var(--wash);
}
.fl-drawing .sheet-fill {
  fill: var(--paper);
}

/* Takes: the same drawing several times, stacked. Paused, the first shows; running, they cycle (line boil). The
   choice travels as inherited custom properties, so the nearest element with data-boil wins. */
[data-boil="off"] {
  --boil: paused;
  --boil-hover: paused;
}
[data-boil="hover"] {
  --boil: paused;
  --boil-hover: running;
}
[data-boil="art"] {
  --boil: running;
  --boil-hover: running;
}
/* Takes stack in one grid cell. The grid sits in the components layer, so a call site's hidden or display wins. The
   cell is as tall as the element, so a call site that gives the drawing a height (h-28 [&>svg]:h-full) fits it in. */
@layer components {
  .fl-takes {
    display: grid;
    grid-template: minmax(0, 1fr) / minmax(0, 1fr);
  }
}
.fl-takes > * {
  grid-area: 1 / 1;
  animation: fl-take calc(var(--take) * 3) steps(1, end) infinite;
  animation-play-state: var(--boil, paused);
}
.fl-takes > * + * {
  opacity: 0;
}
.fl-takes > :nth-child(2) {
  animation-delay: calc(var(--take) * -2);
}
.fl-takes > :nth-child(3) {
  animation-delay: calc(var(--take) * -1);
}
@media (hover: hover) and (pointer: fine) {
  .fl-takes:hover > * {
    animation-play-state: var(--boil-hover, paused);
  }
}
@keyframes fl-take {
  0% {
    opacity: 1;
  }
  33.333% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}
/* Settling after a reroll: settleDrawing() steps data-show through the takes, then removes it. */
.fl-takes[data-show] > * {
  animation: none;
  opacity: 0;
}
.fl-takes[data-show="0"] > :nth-child(1),
.fl-takes[data-show="1"] > :nth-child(2),
.fl-takes[data-show="2"] > :nth-child(3) {
  opacity: 1;
}

/* A drawing waiting to be drawn on the first time it is seen (drawOnView). If no script ever draws it (a static page,
   a failed load), it simply appears after 2.5s. */
.fl-drawing.fl-unseen .ln {
  stroke-dasharray: 0 100000;
  animation: fl-appear 0s linear 2.5s forwards;
}
.fl-drawing.fl-unseen :is(.ink, .wash, .sheet-fill) {
  opacity: 0;
  animation: fl-appear 0s linear 2.5s forwards;
}
@keyframes fl-appear {
  to {
    stroke-dasharray: none;
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fl-takes > * {
    animation: none;
  }
  .fl-drawing.fl-unseen .ln {
    stroke-dasharray: none;
  }
  .fl-drawing.fl-unseen :is(.ink, .wash, .sheet-fill) {
    opacity: 1;
  }
}

/* Forced colours: drawings stay, in the system's text colour. */
@media (forced-colors: active) {
  .fl-drawing .ln,
  .fl-drawing .ink {
    stroke: CanvasText;
  }
  .fl-drawing .ink {
    fill: CanvasText;
  }
  .fl-drawing .wash,
  .fl-drawing .sheet-fill {
    fill: Canvas;
  }
}

/* Fineliner: the Tailwind entry. Import this file once; it brings Tailwind, the tokens, the paper and the frames. */
@import "tailwindcss";
@import "tw-animate-css";
@import "./fonts.css";
@import "./line-sans.generated.css";
@import "./tokens.css";
@import "./stocks.css";
@import "./pens.css";
@import "./textures.generated.css";
@import "./roles.css";
@import "./base.css";
@import "./frames.css";
@import "./drawing.css";
@import "./controls.css";

@custom-variant night (&:where([data-theme="night"], [data-theme="night"] *));
@custom-variant dark (&:where([data-theme="night"], [data-theme="night"] *));
/* calm: inside a calm page or region, unless a lively region sits between (the nearest marked ancestor wins). */
@custom-variant calm (&:where([data-hand="calm"], [data-hand="calm"] *):not(:where([data-hand="calm"] [data-hand="lively"], [data-hand="calm"] [data-hand="lively"] *)));

/* shadcn's state variants (from shadcn/tailwind.css, MIT), so base-nova sources work without that import: Base UI
   marks state with data attributes, Radix-shaped code with data-state. */
@custom-variant data-open {
  &:where([data-state="open"]),
  &:where([data-open]:not([data-open="false"])) {
    @slot;
  }
}
@custom-variant data-closed {
  &:where([data-state="closed"]),
  &:where([data-closed]:not([data-closed="false"])) {
    @slot;
  }
}
@custom-variant data-checked {
  &:where([data-state="checked"]),
  &:where([data-checked]:not([data-checked="false"])) {
    @slot;
  }
}
@custom-variant data-unchecked {
  &:where([data-state="unchecked"]),
  &:where([data-unchecked]:not([data-unchecked="false"])) {
    @slot;
  }
}
@custom-variant data-selected {
  &:where([data-selected="true"]) {
    @slot;
  }
}
@custom-variant data-disabled {
  &:where([data-disabled="true"]),
  &:where([data-disabled]:not([data-disabled="false"])) {
    @slot;
  }
}
@custom-variant data-active {
  &:where([data-state="active"]),
  &:where([data-active]:not([data-active="false"])) {
    @slot;
  }
}
@custom-variant data-horizontal {
  &:where([data-orientation="horizontal"]) {
    @slot;
  }
}
@custom-variant data-vertical {
  &:where([data-orientation="vertical"]) {
    @slot;
  }
}

@theme inline {
  --default-font-family: var(--face-ui);
  --font-read: var(--face-read);
  --font-type: var(--face-type);
  --font-label: var(--face-label);
  --font-hand: var(--face-hand);
  --font-line: var(--face-line);
  --font-inline: var(--face-inline);
  --font-tramline: var(--face-tramline);
  --font-ui: var(--face-ui);
  --font-serif: var(--face-read);
  --font-mono: var(--face-type);

  --text-label: var(--type-label);
  --text-small: var(--type-small);
