/* The label voice as a utility: font, size, case and tracking all follow data-labels. */
@utility label {
  font-family: var(--face-label);
  font-size: var(--type-label);
  font-weight: 500;
  font-variant-caps: var(--label-caps);
  text-transform: var(--label-case);
  letter-spacing: var(--label-track);
  line-height: 1.4;
}

/* The voices. Each package ships its SIL Open Font License. Newsreader carries its optical sizes (opsz), so large
   headings get the display cut and small text the text cut from one family. Gaegu loads only its Latin files, not its
   Korean ones. */
@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/newsreader/opsz-italic.css";
@import "@fontsource/courier-prime/400.css";
@import "@fontsource/courier-prime/700.css";
@import "@fontsource/courier-prime/400-italic.css";
@import "@fontsource/courier-prime/700-italic.css";
@import "@fontsource/gaegu/latin-400.css";
@import "@fontsource/gaegu/latin-700.css";

/* Lines the pen draws round things, in CSS so they render on the server with no script (decision S6). */

/* A frame: top and bottom edges on ::before, sides on ::after. Each edge runs past its corners by a seeded fraction
   of the hand's --over (frameVars() in the pen engine sets --o1…4 and --wob), then a wobble filter bends it. */
@utility frame {
  position: relative;
  isolation: isolate;
  &::before,
  &::after {
    content: "";
    position: absolute;
    z-index: -1;
    pointer-events: none;
    border: 0 solid currentColor;
    filter: var(--wob, var(--wob-1));
  }
  &::before {
    inset: 0 calc(var(--o2, 0.5) * var(--over) * -1) 0
      calc(var(--o4, 0.5) * var(--over) * -1);
    border-block-width: var(--pen-weight);
  }
  &::after {
    inset: calc(var(--o1, 0.5) * var(--over) * -1) 0
      calc(var(--o3, 0.5) * var(--over) * -1) 0;
    border-inline-width: var(--pen-weight);
  }
}

/* Containers: open by default (groups sit on the page, aligned with it), boxed on request (a frame round every
   card). Mark a card's frame with .container-frame and pad it with --card-inset so it follows the setting. --boxed is
   inherited, so the nearest data-containers wins: a boxed region on an open page, or the other way round. */
[data-containers="open"] {
  --boxed: 0;
}
[data-containers="boxed"] {
  --boxed: 1;
}
.container-frame {
  --card-inset: calc(var(--card-spacing, var(--space-snug)) * var(--boxed, 1));
  &::before,
  &::after {
    opacity: var(--boxed, 1);
  }
}

/* A rule: one pen line across its box. The box is taller than the line, or the wobble would be clipped. */
@utility rule {
  height: 0.75rem;
  background: linear-gradient(currentColor, currentColor) center / 100%
    var(--pen-weight) no-repeat;
  filter: var(--wob, var(--wob-3));
}

/* The same line standing up: a box wider than the line, for the same reason. */
@utility rule-y {
  width: 0.75rem;
  background: linear-gradient(currentColor, currentColor) center /
    var(--pen-weight) 100% no-repeat;
  filter: var(--wob, var(--wob-3));
}

/* A pocket: a fill on ::before with the same wobble as a drawn frame, so it never reads as a crisp rectangle. Colour it
   with before:bg-* (ink for the main action, tint for quiet fills and highlighted items); ::after stays free. */
@utility pocket {
  position: relative;
  isolation: isolate;
  &::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: 1px;
    pointer-events: none;
    filter: var(--wob, var(--wob-2));
  }
}

/* A pocket of ink: the solid fill behind the one thing to press or the chosen option. */
@utility ink-fill {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: var(--pen);
  filter: var(--wob, var(--wob-2));
  border-radius: 1px;
}

/* The cartoonist's shadow for surfaces that float: a second line along the right and bottom, no blur. It is a child
   element (<span class="pen-shadow" aria-hidden>), because a frame already uses both pseudo-elements. */
@utility pen-shadow {
  position: absolute;
  inset: 7px -7px -7px 7px;
  z-index: -2;
  border-right: var(--pen-weight) solid currentColor;
  border-bottom: var(--pen-weight) solid currentColor;
  filter: var(--wob-4);
  pointer-events: none;
  /* On a sheet that opens, the shadow follows the paper a beat later. */
  transition: opacity var(--overlay) var(--ease-out) 40ms;
  @starting-style {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pen-shadow {
    transition: none;
  }
}

@media (forced-colors: active) {
  .frame::before,
  .frame::after,
  .rule,
  .rule-y,
  .pocket::before,
  .ink-fill,
  .pen-shadow {
    filter: none;
  }
}

/* Generated by tools/fonts/build.mjs: Naïve Indie Line Sans, the pen as a typeface (MIT). Do not edit by hand. */
@font-face {
  font-family: "Naïve Indie Line Sans";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(data:font/woff2;base64,) format("woff2");
}

/* One pen inks the whole document: text, lines and the rare solid fills. data-pen chooses it; any element can choose
   its own for its subtree. --ink is the reading ink, which is always the pen. */

:root,
[data-pen="navy"] {
  --pen: var(--pen-navy);
  --wash: var(--wash-navy);
}
[data-pen="black"] {
  --pen: var(--pen-black);
  --wash: var(--wash-black);
}
[data-pen="sepia"] {
  --pen: var(--pen-sepia);
  --wash: var(--wash-sepia);
}
[data-pen="forest"] {
  --pen: var(--pen-forest);
  --wash: var(--wash-forest);
}
[data-pen="oxblood"] {
  --pen: var(--pen-oxblood);
  --wash: var(--wash-oxblood);
}

/* Recomputed wherever a pen is chosen, so a region with its own pen gets its own quieter pens and tint. */
:root,
[data-pen] {
  --ink: var(--pen);
  /* Quieter pens for placeholders (still 4.5:1 on flat paper) and for disabled text (exempt from contrast). */
  --pen-quiet: color-mix(
    in srgb,
    var(--pen) var(--quiet-share, 78%),
    var(--paper)
  );
  --pen-faint: color-mix(in srgb, var(--pen) 45%, var(--paper));
  /* Hover and recessed wells: the paper's own darker tone with a breath of ink, so a well reads as paper, not as a
     grey panel. */
  --tint: color-mix(in srgb, var(--pen) 4%, var(--paper-2));
}

/* shadcn's semantic roles, mapped from Fineliner's raw tokens so shadcn-shaped code works unchanged. One pen means
   most roles are the pen or the paper; charts tell series apart by mark (solid, outline, dotted), not by colour. */

:root {
  --background: var(--paper);
  --foreground: var(--pen);
  --card: var(--paper);
  --card-foreground: var(--pen);
  --popover: var(--paper);
  --popover-foreground: var(--pen);
  --primary: var(--pen);
  --primary-foreground: var(--paper);
  --secondary: var(--tint);
  --secondary-foreground: var(--pen);
  --muted: var(--paper-2);
  --muted-foreground: var(--pen);
  --accent: var(--tint);
  --accent-foreground: var(--pen);
  --destructive: var(--correction);
  --border: var(--pen);
  --input: var(--pen);
  --ring: var(--pen);
  --chart-1: var(--pen);
  --chart-2: var(--wash);
  --chart-3: var(--pen);
  --chart-4: var(--wash);
  --chart-5: var(--correction);
  --sidebar: var(--paper);
  --sidebar-foreground: var(--pen);
  --sidebar-primary: var(--pen);
  --sidebar-primary-foreground: var(--paper);
  --sidebar-accent: var(--tint);
