/* Stocks: the paper, and each pen as it reads on that paper. Night is a dark card drawn on with a light gel pen, not an
   inverted page. tools/check-contrast.mjs reads these blocks, so keep one declaration per line. */

:root {
  /* Bond, the brightest stock, is the default paper. */
  --paper: #f4f0e6;
  --paper-2: #ebe5d7;
  --pen-navy: #263152;
  --pen-black: #262421;
  --pen-sepia: #4a3020;
  --pen-forest: #23412f;
  --pen-oxblood: #5c2430;
  /* Each pen thinned: art fills only (a pot, a picture, a wash shape); never text or the only carrier of meaning. */
  --wash-navy: #5b72a8;
  --wash-black: #8d8780;
  --wash-sepia: #a47d5c;
  --wash-forest: #6f9279;
  --wash-oxblood: #a9636e;
  /* The correction pen: errors and destructive actions only. */
  --correction: #962a23;
}

/* Kraft is the darkest stock, so its lighter pens are mixed a little darker to keep 4.5:1 on the textured recess. */
:root[data-stock="kraft"] {
  --paper: #cdb48f;
  --paper-2: #c4a985;
  --pen-sepia: #3e2718;
  --pen-forest: #1b3524;
  --pen-oxblood: #4d1e28;
  --correction: #5e1612;
