  --quiet-share: 88%;
}

:root[data-stock="recycled"] {
  --paper: #ece2ca;
  --paper-2: #e3d7bb;
}

:root[data-theme="night"] {
  --paper: #1b1b1a;
  --paper-2: #252523;
