  --pen-oxblood: #f2d6da;
  --wash-navy: #4f659c;
  --wash-black: #6b6760;
  --wash-sepia: #7d5d43;
  --wash-forest: #4d6a55;
  --wash-oxblood: #7f4650;
  --correction: #f28b80;
}

:root[data-stock="kraft"][data-theme="night"] {
  --paper: #2a2119;
  --paper-2: #342920;
}

:root[data-stock="recycled"][data-theme="night"] {
  --paper: #1c2131;
