/* Fineliner's raw tokens: voices, type scale, leading, spacing, the pen's hand and motion. Paper and pen colours live
   in stocks.css and pens.css.

   Type and spacing follow Golden Ratio Typography: body f = 18px in Newsreader (measured μ 2.498, x 0.636, ratio
   x-correction), measure w = 34rem (544px, about 75 characters). Sizes are f·φ^(n/2); spacing is the primary line
   height (29.5px) times φ^n, rounded to half pixels. Exceptions are marked where they are set. */
:root {
  --face-read: "Newsreader Variable", "Iowan Old Style", Georgia, serif;
  --face-type: "Courier Prime", "Courier New", monospace;
  --face-hand: "Gaegu", "Segoe Print", "Bradley Hand", cursive;
  /* Display lettering: Naïve Indie Line Sans, the pen as a typeface (capitals only), from line-sans.generated.css. */
  --face-line: "Naïve Indie Line Sans", "Avenir Next", "Segoe UI", sans-serif;
  /* Naïve Indie Inline and its tint, from inline.generated.css, which a project imports when it uses the face. */
  --face-inline: "Naïve Indie Inline", var(--face-line);
  --face-inline-fill: "Naïve Indie Inline Fill";
  --face-tramline: "Naïve Indie Tramline", var(--face-line);
  --face-ui: var(--face-read);

  /* Labels: the reading serif in tracked small caps, as on the reference label. data-labels="type" switches them to
     typewriter capitals. */
  --face-label: var(--face-read);
  --label-caps: all-small-caps;
  --label-case: none;
  --label-track: 0.09em;
  --type-label: 0.884rem; /* n −1, 14.2px: small caps sit at x-height, so they read as small labels */

  --type-small: 0.884rem; /* n −1, 14.2px: compact text, metadata */
  --type-ui: 1rem; /* exception: 16px controls, the size below which iOS zooms inputs */
  --type-body: 1.125rem; /* n 0, 18px */
  --type-lead: 1.431rem; /* n 1, 22.9px: h3, lead paragraphs, handwriting */
  --type-h2: 1.82rem; /* n 2, 29.1px */
  --type-h1: 2.315rem; /* n 3, 37.1px */
  --type-title: 2.945rem; /* n 4, 47.1px */
  --type-display: clamp(2.315rem, 1.6rem + 3vw, 3.746rem); /* n 3 → n 5 */

  /* Tuned leading at 544px. Headings are set tight on purpose: they run one to three balanced lines. */
  --lh-body: 1.64;
  --lh-lead: 1.59;
  --lh-small: 1.7;
  --lh-ui: 1.4;
  --lh-heading: 1.12;
  --lh-subhead: 1.3;
  --lh-display: 1.05;
  --lh-hand: 1.1;
  --measure: 34rem;

  --space-hair: 0.4375rem; /* 7px */
  --space-tight: 0.719rem; /* 11.5px */
  --space-snug: 1.125rem; /* 18px */
  --space-line: 1.844rem; /* 29.5px */
  --space-section: 2.969rem; /* 47.5px */
  --space-page: 4.813rem; /* 77px */

  /* Exceptions: touch targets and shadcn convention rather than spacing units. */
  --control-height: 2.75rem;
  --control-height-compact: 2.25rem;

  /* The pen. One weight for every line; it presses harder under the pointer. */
  --pen-weight: 1.35px;
  --pen-weight-pressed: 2px;
  /* The hand: how far edges run past their corners, and which wobble filters frames use. */
  --over: 4px;
  --wob-1: url(#fl-wob-1);
  --wob-2: url(#fl-wob-2);
  --wob-3: url(#fl-wob-3);
  --wob-4: url(#fl-wob-4);
  --wob-5: url(#fl-wob-5);
  --wob-6: url(#fl-wob-6);

  /* Motion is drawing: one curve; quick on controls. */
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --take: 120ms;
  --put-down: 140ms;
  --press: 160ms;
  --overlay: 200ms;
}

[data-hand="calm"] {
  --over: 1.2px;
  --wob-1: url(#fl-wob-calm-1);
  --wob-2: url(#fl-wob-calm-2);
  --wob-3: url(#fl-wob-calm-3);
  --wob-4: url(#fl-wob-calm-4);
  --wob-5: url(#fl-wob-calm-5);
  --wob-6: url(#fl-wob-calm-6);
}

/* Typewriter labels: capitals at 12px, an exception like Patina's button labels; at 11px they read too small. */
[data-labels="type"] {
  --face-label: var(--face-type);
  --label-caps: normal;
  --label-case: uppercase;
  --label-track: 0.07em;
  --type-label: 0.75rem;
}

/* Compact density: every spacing unit half a step down the φ^(n/2) progression (× 0.786); type stays. */
[data-density="compact"] {
  --space-hair: 0.344rem; /* 5.5px */
  --space-tight: 0.563rem; /* 9px */
  --space-snug: 0.906rem; /* 14.5px */
  --space-line: 1.438rem; /* 23px */
  --space-section: 2.344rem; /* 37.5px */
  --space-page: 3.781rem; /* 60.5px */
  --control-height: 2.25rem;
  --control-height-compact: 1.875rem;
}

import {
  APPEARANCE,
  defaultAppearance,
  normalize,
  STORAGE_KEY,
  type Appearance,
} from "./appearance"

/**
 * An inline script for <head> that applies the saved appearance before the first paint, so the page never flashes
 * the wrong paper. Pass the same defaults the app uses at runtime. Unknown saved values fall back to the defaults,
 * as normalize() does.
 */
export function appearanceScript(defaults: Appearance = defaultAppearance) {
  const fallback = JSON.stringify(normalize(defaults))
  const options = JSON.stringify(APPEARANCE)
  return `(()=>{const d=${fallback},o=${options};let a={};try{a=JSON.parse(localStorage.getItem(${JSON.stringify(STORAGE_KEY)})||"{}")||{}}catch{}const r=document.documentElement;for(const k in o){if(!o[k].includes(a[k]))a[k]=d[k];if(k!=="theme")r.dataset[k]=a[k]}r.dataset.theme=a.theme==="system"?(matchMedia("(prefers-color-scheme: dark)").matches?"night":"day"):a.theme;r.dataset.themePreference=a.theme})()`
}

// Appearance lives as attributes on <html>, so CSS does the work and every island reads the same state.
// Saved choices persist in localStorage; "system" follows the operating system's light or dark setting.
// Ported from Patina UI's appearance runtime.

export const APPEARANCE = {
  theme: ["system", "day", "night"],
  stock: ["bond", "recycled", "kraft"],
  /** The one pen that inks the document (styles/pens.css). */
  pen: ["navy", "black", "sepia", "forest", "oxblood"],
  /** How far lines wobble and run past their corners. */
  hand: ["calm", "lively"],
  /** Line boil: drawings redrawn a few times a second, on hover or all the time. */
  boil: ["off", "hover", "art"],
  /** Open: groups sit on the page. Boxed: a frame round every card. */
  containers: ["open", "boxed"],
  /** Labels in the serif's small caps, or typewriter capitals. */
  labels: ["caps", "type"],
  density: ["comfortable", "compact"],
} as const

export type ThemePreference = (typeof APPEARANCE.theme)[number]
export type Stock = (typeof APPEARANCE.stock)[number]
export type Pen = (typeof APPEARANCE.pen)[number]
export type Hand = (typeof APPEARANCE.hand)[number]
export type Boil = (typeof APPEARANCE.boil)[number]
export type Containers = (typeof APPEARANCE.containers)[number]
export type Labels = (typeof APPEARANCE.labels)[number]
export type Density = (typeof APPEARANCE.density)[number]

export interface Appearance {
  theme: ThemePreference
  stock: Stock
  pen: Pen
  hand: Hand
  boil: Boil
  containers: Containers
  labels: Labels
  density: Density
}

export const defaultAppearance: Appearance = {
  theme: "system",
  stock: "bond",
  pen: "navy",
  hand: "lively",
  boil: "hover",
  containers: "open",
  labels: "caps",
  density: "comfortable",
}

export const STORAGE_KEY = "fineliner-appearance"

const KEYS = Object.keys(APPEARANCE) as (keyof Appearance)[]
/** Settings written to <html> under their own name: data-stock, data-pen and so on. */
const ATTRIBUTES = KEYS.filter((key) => key !== "theme")

const pick = <T extends string>(
  options: readonly T[],
  value: unknown,
  fallback: T,
): T => (options.includes(value as T) ? (value as T) : fallback)

/** Keeps only known values, so a stale or hand-edited entry never breaks the page. */
export function normalize(
  value: Partial<Record<keyof Appearance, unknown>>,
  defaults = defaultAppearance,
): Appearance {
  const next: Record<string, string> = {}
  for (const key of KEYS)
    next[key] = pick<string>(APPEARANCE[key], value[key], defaults[key])
  return next as unknown as Appearance
}

export function readSaved(defaults = defaultAppearance): Appearance {
  try {
    return normalize(
      JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}") ?? {},
      defaults,
    )
  } catch {
    return defaults
  }
}

export function save(appearance: Appearance) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appearance))
  } catch {
    // Private windows and blocked storage keep the choice for this page only.
  }
}

export function resolveTheme(theme: ThemePreference): "day" | "night" {
  if (theme !== "system") return theme
  return window.matchMedia("(prefers-color-scheme: dark)").matches
    ? "night"
    : "day"
}

export function apply(
  appearance: Appearance,
  root: HTMLElement = document.documentElement,
) {
  root.dataset.theme = resolveTheme(appearance.theme)
  root.dataset.themePreference = appearance.theme
  for (const key of ATTRIBUTES) root.dataset[key] = appearance[key]
}

/** The appearance currently applied to the document. */
export function current(
  root: HTMLElement = document.documentElement,
): Appearance {
  const value: Partial<Record<keyof Appearance, unknown>> = {
    theme: root.dataset.themePreference,
  }
  for (const key of ATTRIBUTES) value[key] = root.dataset[key]
  return normalize(value)
}

/** The <html> attributes useAppearance watches. */
export const APPEARANCE_ATTRIBUTES = [
  "data-theme-preference",
  ...ATTRIBUTES.map((key) => `data-${key}`),
]

"use client"

import { useCallback, useSyncExternalStore } from "react"
import {
  APPEARANCE_ATTRIBUTES,
  apply,
  current,
  defaultAppearance,
  save,
  type Appearance,
} from "./appearance"

let cache: { key: string; value: Appearance } | undefined

function snapshot(): Appearance {
  const value = current()
  const key = JSON.stringify(value)
  if (cache?.key !== key) cache = { key, value }
  return cache.value
}

function subscribe(onChange: () => void) {
  const observer = new MutationObserver(onChange)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: APPEARANCE_ATTRIBUTES,
  })
  // "system" re-resolves when the operating system switches between light and dark.
  const media = window.matchMedia("(prefers-color-scheme: dark)")
  const follow = () => apply(current())
  media.addEventListener("change", follow)
  return () => {
    observer.disconnect()
    media.removeEventListener("change", follow)
  }
}

/** The document's appearance and a setter that applies and saves a change. Server renders use the defaults. */
export function useAppearance(defaults: Appearance = defaultAppearance) {
  const appearance = useSyncExternalStore(subscribe, snapshot, () => defaults)
  const update = useCallback((change: Partial<Appearance>) => {
    const next = { ...current(), ...change }
    apply(next)
    save(next)
  }, [])
  return [appearance, update] as const
}
